insert into public.mcat_questions(id,body) values
('sample-01', '{"id":"sample-01","topic":"Dilution","section":"C/P","skill":"Concept application","difficulty":"Foundational","prompt":"A 20 mL sample of 0.30 M glucose is diluted to a total volume of 60 mL. What is the final concentration?","options":["0.05 M","0.10 M","0.30 M","0.90 M"],"answer":1,"explanation":"Dilution conserves solute: C₂ = C₁V₁/V₂ = 0.30 × 20/60 = 0.10 M. The volume triples, so concentration falls to one third.","hints":["Use conservation of moles.","Write C₁V₁ = C₂V₂. Use the final total volume."],"target_seconds":60,"version":1,"source":"Original AI-authored starter question · not official MCAT material","passage":null}'::jsonb),
('sample-02', '{"id":"sample-02","topic":"Dilution","section":"C/P","skill":"Concept application","difficulty":"Foundational","prompt":"How many moles of NaCl are present in 250 mL of a 0.20 M solution?","options":["0.80 mol","0.050 mol","50 mol","0.008 mol"],"answer":1,"explanation":"Convert 250 mL to 0.250 L, then n = CV = 0.20 × 0.250 = 0.050 mol.","hints":["Molarity is moles per liter.","Convert the volume to liters before multiplying."],"target_seconds":60,"version":1,"source":"Original AI-authored starter question · not official MCAT material","passage":null}'::jsonb),
('sample-03', '{"id":"sample-03","topic":"Dilution","section":"C/P","skill":"Concept application","difficulty":"Foundational","prompt":"Equal volumes of 0.10 M and 0.30 M glucose are mixed. Assuming additive volumes, what is the resulting concentration?","options":["0.10 M","0.15 M","0.20 M","0.40 M"],"answer":2,"explanation":"For equal volumes, the total moles divided by total volume gives the average concentration: (0.10 + 0.30)/2 = 0.20 M.","hints":["Add moles, not concentrations.","Choose 1 L of each solution to simplify the calculation."],"target_seconds":60,"version":1,"source":"Original AI-authored starter question · not official MCAT material","passage":null}'::jsonb),
('sample-04', '{"id":"sample-04","topic":"Dilution","section":"C/P","skill":"Concept application","difficulty":"Foundational","prompt":"A 0.020 M solution of AlCl₃ dissociates completely. What is the chloride-ion concentration?","options":["0.0067 M","0.020 M","0.040 M","0.060 M"],"answer":3,"explanation":"Each formula unit yields three chloride ions. [Cl⁻] = 3 × 0.020 = 0.060 M.","hints":["Read the chloride subscript.","One mole of AlCl₃ yields three moles of chloride ions."],"target_seconds":45,"version":1,"source":"Original AI-authored starter question · not official MCAT material","passage":null}'::jsonb),
('sample-05', '{"id":"sample-05","topic":"Stoichiometry","section":"C/P","skill":"Concept application","difficulty":"Foundational","prompt":"For 2 H₂ + O₂ → 2 H₂O, 0.30 mol H₂ reacts with excess oxygen. How much water forms?","options":["0.15 mol","0.30 mol","0.60 mol","0.90 mol"],"answer":1,"explanation":"The coefficient ratio H₂:H₂O is 2:2, or 1:1. Therefore 0.30 mol H₂ produces 0.30 mol H₂O.","hints":["Use the reactant-to-product coefficient ratio.","The coefficients of hydrogen and water are equal."],"target_seconds":60,"version":1,"source":"Original AI-authored starter question · not official MCAT material","passage":null}'::jsonb),
('sample-06', '{"id":"sample-06","topic":"Stoichiometry","section":"C/P","skill":"Quantitative reasoning","difficulty":"Foundational","prompt":"For N₂ + 3 H₂ → 2 NH₃, a mixture contains 0.20 mol N₂ and 0.30 mol H₂. What is the maximum NH₃ yield?","options":["0.10 mol","0.20 mol","0.30 mol","0.40 mol"],"answer":1,"explanation":"Hydrogen is limiting: 0.30/3 = 0.10 mol reaction units, producing 0.10 × 2 = 0.20 mol NH₃.","hints":["Identify the limiting reactant first.","Divide each reactant amount by its coefficient and compare."],"target_seconds":90,"version":1,"source":"Original AI-authored starter question · not official MCAT material","passage":null}'::jsonb),
('sample-07', '{"id":"sample-07","topic":"Stoichiometry","section":"C/P","skill":"Quantitative reasoning","difficulty":"Foundational","prompt":"CaCO₃ → CaO + CO₂. If 5.0 g CaCO₃ decomposes completely, how many grams of CO₂ form? Use 100 g/mol for CaCO₃ and 44 g/mol for CO₂.","options":["1.1 g","2.2 g","4.4 g","5.0 g"],"answer":1,"explanation":"5.0/100 = 0.050 mol CaCO₃. The 1:1 ratio yields 0.050 mol CO₂; multiplying by 44 g/mol gives 2.2 g.","hints":["Convert mass to moles first.","Use the 1:1 mole ratio, then convert product moles to grams."],"target_seconds":90,"version":1,"source":"Original AI-authored starter question · not official MCAT material","passage":null}'::jsonb),
('sample-08', '{"id":"sample-08","topic":"Stoichiometry","section":"C/P","skill":"Quantitative reasoning","difficulty":"Foundational","prompt":"For 4 Al + 3 O₂ → 2 Al₂O₃, 0.20 mol Al reacts completely with 0.25 mol O₂ initially present. How much O₂ remains?","options":["0.05 mol","0.10 mol","0.15 mol","0.20 mol"],"answer":1,"explanation":"O₂ consumed = 0.20 × 3/4 = 0.15 mol. Remaining O₂ = 0.25 − 0.15 = 0.10 mol.","hints":["Calculate oxygen consumed before subtracting.","Multiply aluminum moles by 3/4, then subtract from the initial oxygen."],"target_seconds":90,"version":1,"source":"Original AI-authored starter question · not official MCAT material","passage":null}'::jsonb),
('sample-09', '{"id":"sample-09","topic":"Enzyme kinetics","section":"B/B","skill":"Concept application","difficulty":"Foundational","prompt":"A reversible competitive inhibitor has which effect on Michaelis–Menten parameters?","options":["Decreases Vmax only","Increases apparent Km; Vmax unchanged","Decreases Km and Vmax","Increases Vmax only"],"answer":1,"explanation":"A competitive inhibitor competes for the active site. More substrate is needed for half-maximal velocity, increasing apparent Km; sufficient substrate restores the same Vmax.","hints":["Consider whether excess substrate can overcome inhibition.","Competitive inhibition changes substrate concentration needed, not maximum catalytic capacity."],"target_seconds":60,"version":1,"source":"Original AI-authored starter question · not official MCAT material","passage":null}'::jsonb),
('sample-10', '{"id":"sample-10","topic":"Enzyme kinetics","section":"B/B","skill":"Concept application","difficulty":"Foundational","prompt":"For an enzyme following Michaelis–Menten kinetics, what is v when [S] = Km?","options":["Vmax","Vmax/4","Vmax/2","2Vmax"],"answer":2,"explanation":"v = Vmax[S]/(Km + [S]). When [S] = Km, the numerator is VmaxKm and the denominator is 2Km, giving Vmax/2.","hints":["Substitute into the Michaelis–Menten equation.","The denominator becomes twice Km."],"target_seconds":60,"version":1,"source":"Original AI-authored starter question · not official MCAT material","passage":null}'::jsonb),
('sample-11', '{"id":"sample-11","topic":"Enzyme kinetics","section":"B/B","skill":"Concept application","difficulty":"Foundational","prompt":"An ideal pure noncompetitive inhibitor changes which parameters?","options":["Vmax decreases; Km unchanged","Vmax unchanged; Km increases","Both increase","Both remain unchanged"],"answer":0,"explanation":"In pure noncompetitive inhibition, inhibitor affinity for free enzyme and enzyme–substrate complex is equal. Vmax falls while Km stays the same. Mixed inhibition need not preserve Km.","hints":["Distinguish pure noncompetitive inhibition from mixed inhibition.","Effective catalytic capacity decreases without changing substrate affinity in the ideal case."],"target_seconds":60,"version":1,"source":"Original AI-authored starter question · not official MCAT material","passage":null}'::jsonb),
('sample-12', '{"id":"sample-12","topic":"Enzyme kinetics","section":"B/B","skill":"Concept application","difficulty":"Foundational","prompt":"On a Lineweaver–Burk plot of 1/v against 1/[S], the y-intercept equals:","options":["Km","−1/Km","Vmax","1/Vmax"],"answer":3,"explanation":"Taking the reciprocal gives 1/v = (Km/Vmax)(1/[S]) + 1/Vmax. The constant term is the y-intercept.","hints":["Compare the reciprocal equation with y = mx + b.","The term that does not multiply 1/[S] is the intercept."],"target_seconds":60,"version":1,"source":"Original AI-authored starter question · not official MCAT material","passage":null}'::jsonb),
('sample-13', '{"id":"sample-13","topic":"Membrane transport","section":"B/B","skill":"Concept application","difficulty":"Foundational","prompt":"A substance moves down its concentration gradient through a carrier protein without ATP use. This is:","options":["Primary active transport","Facilitated diffusion","Endocytosis","Secondary active transport"],"answer":1,"explanation":"Facilitated diffusion uses a membrane protein to move a substance down its gradient without direct energy input. Active transport couples movement to an energy source.","hints":["Consider both direction and energy use.","A carrier protein does not automatically make transport active."],"target_seconds":45,"version":1,"source":"Original AI-authored starter question · not official MCAT material","passage":null}'::jsonb),
('sample-14', '{"id":"sample-14","topic":"Membrane transport","section":"B/B","skill":"Concept application","difficulty":"Foundational","prompt":"The sodium–potassium ATPase typically transports, per ATP hydrolyzed:","options":["3 Na⁺ out and 2 K⁺ in","2 Na⁺ out and 3 K⁺ in","3 Na⁺ in and 2 K⁺ out","2 Na⁺ in and 2 K⁺ out"],"answer":0,"explanation":"The pump exports three sodium ions and imports two potassium ions per ATP, creating a net outward positive charge.","hints":["The pump is electrogenic.","More positive ions leave than enter in each cycle."],"target_seconds":45,"version":1,"source":"Original AI-authored starter question · not official MCAT material","passage":null}'::jsonb),
('sample-15', '{"id":"sample-15","topic":"Membrane transport","section":"B/B","skill":"Concept application","difficulty":"Foundational","prompt":"A cell is placed in a solution with a higher concentration of nonpenetrating solutes than its cytoplasm. What initially happens?","options":["Water enters and the cell swells","Water leaves and the cell shrinks","No net water movement","Solutes must all leave the cell"],"answer":1,"explanation":"The external solution is hypertonic. Water moves outward toward the higher effective solute concentration, shrinking the cell.","hints":["Only nonpenetrating solutes determine this tonicity comparison.","Water moves toward the compartment with more nonpenetrating solute."],"target_seconds":60,"version":1,"source":"Original AI-authored starter question · not official MCAT material","passage":null}'::jsonb),
('sample-16', '{"id":"sample-16","topic":"Membrane transport","section":"B/B","skill":"Concept application","difficulty":"Foundational","prompt":"Which molecule most readily crosses a pure phospholipid bilayer by simple diffusion?","options":["Na⁺","Glucose","O₂","A large charged peptide"],"answer":2,"explanation":"Small nonpolar molecules such as oxygen cross the hydrophobic bilayer readily. Ions and large polar molecules face much larger barriers.","hints":["Think about the hydrophobic interior of the membrane.","Small size and lack of charge favor simple diffusion."],"target_seconds":45,"version":1,"source":"Original AI-authored starter question · not official MCAT material","passage":null}'::jsonb),
('sample-17', '{"id":"sample-17","topic":"Circuits","section":"C/P","skill":"Concept application","difficulty":"Foundational","prompt":"A 12 V potential difference is applied across a 4 Ω resistor. What current flows?","options":["0.33 A","3 A","8 A","48 A"],"answer":1,"explanation":"Ohm’s law gives I = V/R = 12/4 = 3 A.","hints":["Use Ohm’s law.","Solve V = IR for current."],"target_seconds":60,"version":1,"source":"Original AI-authored starter question · not official MCAT material","passage":null}'::jsonb),
('sample-18', '{"id":"sample-18","topic":"Circuits","section":"C/P","skill":"Quantitative reasoning","difficulty":"Foundational","prompt":"Two resistors of 3 Ω and 6 Ω are connected in parallel. What is their equivalent resistance?","options":["2 Ω","3 Ω","9 Ω","18 Ω"],"answer":0,"explanation":"1/R = 1/3 + 1/6 = 1/2, so R = 2 Ω. Parallel resistance is lower than the smallest branch resistance.","hints":["Add reciprocals for parallel resistors.","Use a common denominator of six."],"target_seconds":75,"version":1,"source":"Original AI-authored starter question · not official MCAT material","passage":null}'::jsonb),
('sample-19', '{"id":"sample-19","topic":"Circuits","section":"C/P","skill":"Concept application","difficulty":"Foundational","prompt":"A resistor carries 2 A with a 6 V potential difference. How much power does it dissipate?","options":["3 W","8 W","12 W","24 W"],"answer":2,"explanation":"Electrical power P = IV = 2 × 6 = 12 W.","hints":["Power is energy transferred per unit time.","Use P = IV."],"target_seconds":45,"version":1,"source":"Original AI-authored starter question · not official MCAT material","passage":null}'::jsonb),
('sample-20', '{"id":"sample-20","topic":"Circuits","section":"C/P","skill":"Concept application","difficulty":"Foundational","prompt":"Two ideal resistors in series have which quantity necessarily equal through each?","options":["Voltage drop","Resistance","Power dissipation","Current"],"answer":3,"explanation":"A series path has no branch points, so charge conservation requires the same current through both resistors. Voltage drops depend on resistance.","hints":["Consider conservation of charge along a single path.","Charge cannot accumulate indefinitely between the resistors."],"target_seconds":45,"version":1,"source":"Original AI-authored starter question · not official MCAT material","passage":null}'::jsonb),
('sample-21', '{"id":"sample-21","topic":"Learning & memory","section":"P/S","skill":"Concept application","difficulty":"Foundational","prompt":"A student studies more often after an unpleasant reminder stops whenever they study. This illustrates:","options":["Positive punishment","Negative reinforcement","Negative punishment","Extinction"],"answer":1,"explanation":"Removing an aversive stimulus increases studying, so this is negative reinforcement. Negative means removal; reinforcement means the behavior increases.","hints":["Separate adding/removing a stimulus from increasing/decreasing behavior.","An unpleasant stimulus is removed and the behavior increases."],"target_seconds":60,"version":1,"source":"Original AI-authored starter question · not official MCAT material","passage":null}'::jsonb),
('sample-22', '{"id":"sample-22","topic":"Learning & memory","section":"P/S","skill":"Concept application","difficulty":"Foundational","prompt":"An old password interferes with remembering a new password. This is:","options":["Retroactive interference","Proactive interference","Classical conditioning","State-dependent memory"],"answer":1,"explanation":"Proactive interference occurs when earlier learning disrupts recall of newer material. Retroactive interference is the reverse direction.","hints":["Identify which memory interferes with which.","The old memory acts forward on the new memory."],"target_seconds":45,"version":1,"source":"Original AI-authored starter question · not official MCAT material","passage":null}'::jsonb),
('sample-23', '{"id":"sample-23","topic":"Learning & memory","section":"P/S","skill":"Concept application","difficulty":"Foundational","prompt":"A previously conditioned response weakens when the conditioned stimulus is repeatedly presented without the unconditioned stimulus. This is:","options":["Generalization","Acquisition","Extinction","Discrimination"],"answer":2,"explanation":"Repeated unreinforced presentations of the conditioned stimulus reduce the conditioned response: extinction. This does not necessarily erase the original association.","hints":["The association is no longer reinforced.","The response becomes weaker over repeated trials."],"target_seconds":45,"version":1,"source":"Original AI-authored starter question · not official MCAT material","passage":null}'::jsonb),
('sample-24', '{"id":"sample-24","topic":"Learning & memory","section":"P/S","skill":"Concept application","difficulty":"Foundational","prompt":"Remembering how to ride a bicycle primarily involves:","options":["Episodic memory","Semantic memory","Procedural memory","Sensory memory"],"answer":2,"explanation":"Procedural memory supports learned skills and actions. Episodic memory concerns events; semantic memory concerns facts and concepts.","hints":["Distinguish knowing how from knowing that.","Motor skills are a form of implicit memory."],"target_seconds":45,"version":1,"source":"Original AI-authored starter question · not official MCAT material","passage":null}'::jsonb),
('sample-25', '{"id":"sample-25","topic":"Dilution","section":"C/P","skill":"Concept application","difficulty":"Foundational","prompt":"What volume of 2.0 M stock is required to prepare 100 mL of 0.10 M solution?","options":["5 mL","10 mL","20 mL","50 mL"],"answer":0,"explanation":"C₁V₁ = C₂V₂, so V₁ = 0.10 × 100 / 2.0 = 5 mL. Dilute that stock to a final total of 100 mL.","hints":["Conserve solute moles.","Rearrange the dilution equation to solve for the stock volume."],"target_seconds":60,"version":1,"source":"Original AI-authored starter question · not official MCAT material","passage":null}'::jsonb),
('sample-26', '{"id":"sample-26","topic":"Dilution","section":"C/P","skill":"Concept application","difficulty":"Foundational","prompt":"100 mL of 0.50 M glucose loses water by evaporation until 50 mL remains. No glucose is lost. What is the new concentration?","options":["0.25 M","0.50 M","1.0 M","2.0 M"],"answer":2,"explanation":"Halving the volume while retaining all solute doubles its concentration, from 0.50 M to 1.0 M.","hints":["The number of solute moles stays constant.","Divide the original volume by the remaining volume."],"target_seconds":60,"version":1,"source":"Original AI-authored starter question · not official MCAT material","passage":null}'::jsonb),
('sample-27', '{"id":"sample-27","topic":"Stoichiometry","section":"C/P","skill":"Concept application","difficulty":"Foundational","prompt":"2 KClO₃ → 2 KCl + 3 O₂. How much O₂ forms when 0.40 mol KClO₃ decomposes completely?","options":["0.20 mol","0.40 mol","0.60 mol","1.20 mol"],"answer":2,"explanation":"The O₂:KClO₃ coefficient ratio is 3:2. Thus 0.40 × 3/2 = 0.60 mol O₂ forms.","hints":["Read the balanced coefficients.","Multiply the reactant amount by the product-to-reactant ratio."],"target_seconds":60,"version":1,"source":"Original AI-authored starter question · not official MCAT material","passage":null}'::jsonb),
('sample-28', '{"id":"sample-28","topic":"Stoichiometry","section":"C/P","skill":"Concept application","difficulty":"Foundational","prompt":"A reaction has a theoretical product yield of 8.0 g and an actual yield of 6.0 g. What is the percent yield?","options":["25%","60%","75%","133%"],"answer":2,"explanation":"Percent yield = actual/theoretical × 100 = 6.0/8.0 × 100 = 75%.","hints":["Compare the obtained mass with the maximum predicted mass.","Actual yield is the numerator."],"target_seconds":60,"version":1,"source":"Original AI-authored starter question · not official MCAT material","passage":null}'::jsonb),
('sample-29', '{"id":"sample-29","topic":"Enzyme kinetics","section":"B/B","skill":"Concept application","difficulty":"Foundational","prompt":"At saturating substrate concentration, doubling the amount of active enzyme does what to Vmax?","options":["Halves it","Leaves it unchanged","Doubles it","Quadruples it"],"answer":2,"explanation":"Vmax = kcat × total active enzyme concentration. Doubling active enzyme doubles Vmax if other conditions remain constant.","hints":["Vmax depends on the number of catalytic sites.","The proportionality to enzyme concentration is linear."],"target_seconds":60,"version":1,"source":"Original AI-authored starter question · not official MCAT material","passage":null}'::jsonb),
('sample-30', '{"id":"sample-30","topic":"Enzyme kinetics","section":"B/B","skill":"Quantitative reasoning","difficulty":"Foundational","prompt":"An enzyme has Vmax = 90 μmol/min and Km = 2 mM. At [S] = 4 mM, what is its initial rate under Michaelis–Menten kinetics?","options":["30 μmol/min","45 μmol/min","60 μmol/min","90 μmol/min"],"answer":2,"explanation":"v = Vmax[S]/(Km + [S]) = 90 × 4/(2 + 4) = 60 μmol/min.","hints":["Use the Michaelis–Menten equation.","The substrate fraction is 4/(2 + 4)."],"target_seconds":90,"version":1,"source":"Original AI-authored starter question · not official MCAT material","passage":null}'::jsonb),
('sample-31', '{"id":"sample-31","topic":"Membrane transport","section":"B/B","skill":"Concept application","difficulty":"Foundational","prompt":"A sodium–glucose symporter uses the sodium gradient to move glucose against its gradient. This is:","options":["Simple diffusion","Facilitated diffusion","Primary active transport","Secondary active transport"],"answer":3,"explanation":"Secondary active transport couples favorable movement of one species down its electrochemical gradient to unfavorable movement of another. The transporter does not directly hydrolyze ATP.","hints":["Identify the immediate energy source for this transporter.","An existing ion gradient provides the energy."],"target_seconds":60,"version":1,"source":"Original AI-authored starter question · not official MCAT material","passage":null}'::jsonb),
('sample-32', '{"id":"sample-32","topic":"Membrane transport","section":"B/B","skill":"Concept application","difficulty":"Foundational","prompt":"In a pure lipid bilayer, increasing the proportion of unsaturated fatty-acid tails generally has what effect at a fixed moderate temperature?","options":["Increases fluidity","Decreases fluidity","Eliminates the hydrophobic core","Makes all ions freely permeable"],"answer":0,"explanation":"Cis double bonds introduce kinks that reduce close packing of lipid tails, generally increasing membrane fluidity.","hints":["Consider how tightly the tails can pack.","Kinked tails have fewer close contacts with neighboring tails."],"target_seconds":60,"version":1,"source":"Original AI-authored starter question · not official MCAT material","passage":null}'::jsonb),
('sample-33', '{"id":"sample-33","topic":"Circuits","section":"C/P","skill":"Quantitative reasoning","difficulty":"Foundational","prompt":"A 2 Ω and a 4 Ω resistor are connected in series to an ideal 12 V source. What is the voltage across the 4 Ω resistor?","options":["2 V","4 V","6 V","8 V"],"answer":3,"explanation":"Total resistance is 6 Ω, so current is 12/6 = 2 A. The drop across 4 Ω is IR = 2 × 4 = 8 V.","hints":["Find total resistance, then the series current.","Use the common current to calculate the drop across 4 Ω."],"target_seconds":90,"version":1,"source":"Original AI-authored starter question · not official MCAT material","passage":null}'::jsonb),
('sample-34', '{"id":"sample-34","topic":"Circuits","section":"C/P","skill":"Concept application","difficulty":"Foundational","prompt":"A 2 μF capacitor is connected across a 3 V source. How much charge does it store?","options":["0.67 μC","1.5 μC","5 μC","6 μC"],"answer":3,"explanation":"Q = CV = 2 μF × 3 V = 6 μC.","hints":["Capacitance relates stored charge to voltage.","Use Q = CV and retain the micro prefix."],"target_seconds":60,"version":1,"source":"Original AI-authored starter question · not official MCAT material","passage":null}'::jsonb),
('sample-35', '{"id":"sample-35","topic":"Learning & memory","section":"P/S","skill":"Concept application","difficulty":"Foundational","prompt":"Remembering what you ate at your own birthday dinner last year primarily involves:","options":["Procedural memory","Episodic memory","Classical conditioning","Sensory memory"],"answer":1,"explanation":"Episodic memory concerns personally experienced events in their temporal and contextual setting.","hints":["This is a personally experienced event.","Distinguish autobiographical events from general facts."],"target_seconds":45,"version":1,"source":"Original AI-authored starter question · not official MCAT material","passage":null}'::jsonb),
('sample-36', '{"id":"sample-36","topic":"Learning & memory","section":"P/S","skill":"Concept application","difficulty":"Foundational","prompt":"A learned response occurs to a new stimulus similar to the original conditioned stimulus. This is:","options":["Stimulus discrimination","Spontaneous recovery","Stimulus generalization","Negative reinforcement"],"answer":2,"explanation":"Stimulus generalization occurs when stimuli resembling the conditioned stimulus also evoke the learned response.","hints":["Focus on the similarity between the two stimuli.","The response extends beyond the exact original stimulus."],"target_seconds":45,"version":1,"source":"Original AI-authored starter question · not official MCAT material","passage":null}'::jsonb),
('expansion-01-01-01', '{"id":"expansion-01-01-01","topic":"Acids & bases","section":"C/P","prompt":"A buffer contains equal concentrations of a weak acid and its conjugate base. The acid has pKa = 6.8. What is the buffer pH?","options":["3.4","6.8","7.0","13.6"],"answer":1,"explanation":"The Henderson–Hasselbalch equation gives pH = pKa + log([base]/[acid]). Equal concentrations give log(1) = 0, so pH = 6.8. A buffer need not have neutral pH.","hints":["Compare the base-to-acid ratio.","Use pH = pKa + log([base]/[acid]); log(1) is zero."],"target_seconds":60,"skill":"Quantitative reasoning","difficulty":"Foundational","version":1,"source":"Original AI-authored practice · not official or calibrated MCAT material","passage":null}'::jsonb),
('expansion-01-01-02', '{"id":"expansion-01-01-02","topic":"Acids & bases","section":"C/P","prompt":"A weak acid has pKa = 5.0. At pH 6.0, what is the ratio of conjugate base to undissociated acid?","options":["1:10","1:1","10:1","100:1"],"answer":2,"explanation":"pH − pKa = log([base]/[acid]) = 1. The ratio is therefore 10:1. Higher pH favors the deprotonated form.","hints":["Subtract pKa from pH.","Convert a base-10 logarithm of 1 into a concentration ratio."],"target_seconds":75,"skill":"Quantitative reasoning","difficulty":"Foundational","version":1,"source":"Original AI-authored practice · not official or calibrated MCAT material","passage":null}'::jsonb),
('expansion-01-01-03', '{"id":"expansion-01-01-03","topic":"Acids & bases","section":"C/P","prompt":"At 25 °C, a dilute aqueous solution has [H+] = 1 × 10⁻³ M. What is [OH−]? Use Kw = 1 × 10⁻¹⁴.","options":["1 × 10⁻¹¹ M","1 × 10⁻⁷ M","1 × 10⁻³ M","1 × 10¹¹ M"],"answer":0,"explanation":"Kw = [H+][OH−]. Dividing 10⁻¹⁴ by 10⁻³ gives [OH−] = 10⁻¹¹ M. The acidic solution has less hydroxide than neutral water.","hints":["Use the product of the two ion concentrations.","When dividing powers of ten, subtract the exponents."],"target_seconds":60,"skill":"Quantitative reasoning","difficulty":"Foundational","version":1,"source":"Original AI-authored practice · not official or calibrated MCAT material","passage":null}'::jsonb),
('expansion-01-01-04', '{"id":"expansion-01-01-04","topic":"Acids & bases","section":"C/P","prompt":"A small amount of strong acid is added to an acetate buffer containing appreciable acetic acid and acetate. Which reaction primarily limits the pH change?","options":["Acetic acid consumes added H+","Water converts all acetate into hydroxide","Acetate releases H+","Acetate accepts H+ to form acetic acid"],"answer":3,"explanation":"The conjugate base acetate accepts added protons, forming acetic acid. This consumes much of the added H+ while the buffer remains within its capacity.","hints":["Identify the proton acceptor in the buffer.","The negatively charged conjugate base can become the neutral weak acid."],"target_seconds":60,"skill":"Concept application","difficulty":"Foundational","version":1,"source":"Original AI-authored practice · not official or calibrated MCAT material","passage":null}'::jsonb),
('expansion-01-01-05', '{"id":"expansion-01-01-05","topic":"Acids & bases","section":"C/P","prompt":"At the equivalence point of a weak monoprotic acid titrated with a strong base at 25 °C, the solution is generally:","options":["Acidic because some titrant remains","Basic because the conjugate base reacts with water","Neutral for every acid","Basic because the weak acid releases OH− directly"],"answer":1,"explanation":"At equivalence the acid has been converted to its conjugate base. That base hydrolyzes water to produce OH−, so pH exceeds 7. Excess strong base is not required.","hints":["Consider the species remaining after neutralization.","Write A− + H₂O ⇌ HA + OH−."],"target_seconds":60,"skill":"Concept application","difficulty":"Foundational","version":1,"source":"Original AI-authored practice · not official or calibrated MCAT material","passage":null}'::jsonb),
('expansion-01-01-06', '{"id":"expansion-01-01-06","topic":"Acids & bases","section":"C/P","prompt":"A monoprotic weak acid is half-neutralized during titration with a strong base. Which statement holds under the usual dilute-solution approximation?","options":["pH = pKa","pH = 7 for every acid","[H+] equals the initial acid concentration","The conjugate base concentration is zero"],"answer":0,"explanation":"Half-neutralization leaves equal amounts of HA and A− in the same solution. Their concentration ratio is one, so the Henderson–Hasselbalch equation reduces to pH = pKa.","hints":["Track how much HA has been converted into A−.","At halfway to equivalence, the two buffer components have equal concentrations."],"target_seconds":60,"skill":"Concept application","difficulty":"Foundational","version":1,"source":"Original AI-authored practice · not official or calibrated MCAT material","passage":null}'::jsonb),
('expansion-01-02-01', '{"id":"expansion-01-02-01","topic":"Thermodynamics & equilibrium","section":"C/P","prompt":"For a reaction, ΔH = −40 kJ/mol and ΔS = −100 J/(mol·K). What is ΔG at 300 K?","options":["−70 kJ/mol","+10 kJ/mol","−10 kJ/mol","+70 kJ/mol"],"answer":2,"explanation":"Convert entropy to −0.100 kJ/(mol·K). ΔG = ΔH − TΔS = −40 − 300(−0.100) = −10 kJ/mol. Matching units is essential.","hints":["Use ΔG = ΔH − TΔS.","Convert joules to kilojoules before multiplying entropy by temperature."],"target_seconds":90,"skill":"Quantitative reasoning","difficulty":"Foundational","version":1,"source":"Original AI-authored practice · not official or calibrated MCAT material","passage":null}'::jsonb),
('expansion-01-02-02', '{"id":"expansion-01-02-02","topic":"Thermodynamics & equilibrium","section":"C/P","prompt":"An enzyme catalyzes a reversible reaction at constant temperature. Which quantity does the enzyme change?","options":["The equilibrium constant","The activation free-energy barrier","The standard reaction free energy","The equilibrium product-to-reactant ratio"],"answer":1,"explanation":"An enzyme lowers the activation barrier and accelerates approach to equilibrium. It changes neither the free-energy difference between reactants and products nor the equilibrium constant.","hints":["Separate reaction speed from equilibrium position.","A catalyst provides a lower-barrier pathway for both directions."],"target_seconds":60,"skill":"Concept application","difficulty":"Foundational","version":1,"source":"Original AI-authored practice · not official or calibrated MCAT material","passage":null}'::jsonb),
('expansion-01-02-03', '{"id":"expansion-01-02-03","topic":"Thermodynamics & equilibrium","section":"C/P","prompt":"For a reaction as written, the reaction quotient Q is less than the equilibrium constant K. Which direction is thermodynamically favored?","options":["Reverse until all product disappears","Neither direction because Q is always K","Forward only if a catalyst is present","Forward toward equilibrium"],"answer":3,"explanation":"ΔG = RT ln(Q/K). If Q < K, the logarithm is negative, so the forward reaction is favored. This predicts direction, not how quickly the reaction proceeds.","hints":["Compare Q/K with one.","The natural logarithm of a positive number below one is negative."],"target_seconds":60,"skill":"Concept application","difficulty":"Foundational","version":1,"source":"Original AI-authored practice · not official or calibrated MCAT material","passage":null}'::jsonb),
('expansion-01-02-04', '{"id":"expansion-01-02-04","topic":"Thermodynamics & equilibrium","section":"C/P","prompt":"Heat is a product of an exothermic reversible reaction. At constant pressure, increasing temperature shifts equilibrium toward:","options":["Reactants","Products","The side with more catalyst","Products only if volumes are equal"],"answer":0,"explanation":"Increasing temperature favors the endothermic direction, which consumes heat. For a forward exothermic reaction, that direction is toward reactants.","hints":["Treat heat as a product for this qualitative prediction.","The system responds to added heat by favoring the direction that consumes it."],"target_seconds":60,"skill":"Concept application","difficulty":"Foundational","version":1,"source":"Original AI-authored practice · not official or calibrated MCAT material","passage":null}'::jsonb),
('expansion-01-02-05', '{"id":"expansion-01-02-05","topic":"Thermodynamics & equilibrium","section":"C/P","prompt":"Under the same cellular conditions, reaction A has ΔG = +12 kJ/mol and reaction B has ΔG = −30 kJ/mol. If mechanistically coupled one-to-one, what is the net ΔG?","options":["+42 kJ/mol","+18 kJ/mol","−18 kJ/mol","−42 kJ/mol"],"answer":2,"explanation":"Free-energy changes add for coupled reactions: +12 + (−30) = −18 kJ/mol. Merely placing unrelated reactions together would not establish mechanistic coupling.","hints":["Free-energy changes are additive.","Add the signed values for one occurrence of each reaction."],"target_seconds":60,"skill":"Quantitative reasoning","difficulty":"Foundational","version":1,"source":"Original AI-authored practice · not official or calibrated MCAT material","passage":null}'::jsonb),
('expansion-01-02-06', '{"id":"expansion-01-02-06","topic":"Thermodynamics & equilibrium","section":"C/P","prompt":"A system reaches dynamic chemical equilibrium in a closed container. Which statement is correct?","options":["Reactant and product concentrations must be equal","Forward and reverse reaction rates are equal","Molecular reactions stop","The equilibrium constant becomes zero"],"answer":1,"explanation":"At dynamic equilibrium the opposing rates match, so macroscopic concentrations remain constant. Their values need not be equal, and molecules continue reacting.","hints":["Dynamic equilibrium is about matching rates.","Constant concentration does not mean equal concentration or no molecular activity."],"target_seconds":45,"skill":"Concept application","difficulty":"Foundational","version":1,"source":"Original AI-authored practice · not official or calibrated MCAT material","passage":null}'::jsonb),
('expansion-01-03-01', '{"id":"expansion-01-03-01","topic":"Fluids & gases","section":"C/P","prompt":"Water flows steadily through a rigid pipe. If its cross-sectional area falls to half its original value, how does speed change? Assume incompressible flow with no branches.","options":["It halves","It stays constant","It falls to one fourth","It doubles"],"answer":3,"explanation":"Continuity requires A₁v₁ = A₂v₂. Halving area doubles speed so the same fluid volume passes each section per unit time.","hints":["Conserve volume flow rate.","The product of area and speed remains constant."],"target_seconds":60,"skill":"Quantitative reasoning","difficulty":"Foundational","version":1,"source":"Original AI-authored practice · not official or calibrated MCAT material","passage":null}'::jsonb),
('expansion-01-03-02', '{"id":"expansion-01-03-02","topic":"Fluids & gases","section":"C/P","prompt":"What is the gauge pressure 2.0 m below the surface of a stationary freshwater pool? Use density 1000 kg/m³ and g = 10 m/s².","options":["2.0 × 10⁴ Pa","2.0 × 10³ Pa","1.0 × 10⁵ Pa","2.0 × 10⁵ Pa"],"answer":0,"explanation":"Gauge pressure is ρgh = 1000 × 10 × 2.0 = 20,000 Pa. Atmospheric pressure would be added only to calculate absolute pressure.","hints":["Gauge pressure excludes atmospheric pressure.","Multiply density, gravitational acceleration, and depth."],"target_seconds":75,"skill":"Quantitative reasoning","difficulty":"Foundational","version":1,"source":"Original AI-authored practice · not official or calibrated MCAT material","passage":null}'::jsonb),
('expansion-01-03-03', '{"id":"expansion-01-03-03","topic":"Fluids & gases","section":"C/P","prompt":"For ideal laminar flow through a tube, the radius is doubled while pressure difference, length, and viscosity stay constant. By what factor does volume flow rate change?","options":["2","4","16","1/16"],"answer":2,"explanation":"Poiseuille''s law gives flow proportional to r⁴. Doubling radius multiplies flow by 2⁴ = 16, under the specified laminar-flow assumptions.","hints":["Recall the radius dependence in Poiseuille''s law.","Raise the radius multiplication factor to the fourth power."],"target_seconds":60,"skill":"Quantitative reasoning","difficulty":"Foundational","version":1,"source":"Original AI-authored practice · not official or calibrated MCAT material","passage":null}'::jsonb),
('expansion-01-03-04', '{"id":"expansion-01-03-04","topic":"Fluids & gases","section":"C/P","prompt":"A sealed ideal gas is heated from 300 K to 450 K at constant volume. If its initial pressure is 100 kPa, what is its final pressure?","options":["67 kPa","150 kPa","200 kPa","450 kPa"],"answer":1,"explanation":"At fixed amount and volume, P/T is constant. P₂ = 100 × 450/300 = 150 kPa. Temperature ratios must use kelvin.","hints":["Use the ideal gas law with amount and volume fixed.","Multiply initial pressure by the ratio of absolute temperatures."],"target_seconds":75,"skill":"Quantitative reasoning","difficulty":"Foundational","version":1,"source":"Original AI-authored practice · not official or calibrated MCAT material","passage":null}'::jsonb),
('expansion-01-03-05', '{"id":"expansion-01-03-05","topic":"Fluids & gases","section":"C/P","prompt":"An ideal gas mixture contains 20% oxygen by mole fraction at a total pressure of 150 kPa. What is the oxygen partial pressure?","options":["30 kPa","75 kPa","130 kPa","750 kPa"],"answer":0,"explanation":"Dalton''s law gives partial pressure = mole fraction × total pressure = 0.20 × 150 = 30 kPa.","hints":["A component contributes its mole fraction of the total pressure.","Convert 20% to 0.20 before multiplying."],"target_seconds":60,"skill":"Quantitative reasoning","difficulty":"Foundational","version":1,"source":"Original AI-authored practice · not official or calibrated MCAT material","passage":null}'::jsonb),
('expansion-01-03-06', '{"id":"expansion-01-03-06","topic":"Fluids & gases","section":"C/P","prompt":"A fully submerged rigid object is moved deeper in an incompressible liquid of uniform density. Its volume stays constant. What happens to its buoyant force?","options":["It increases with absolute pressure","It decreases with depth","It becomes zero","It remains constant"],"answer":3,"explanation":"Buoyant force equals the weight of displaced liquid, ρVg. Density and displaced volume remain unchanged, so greater depth does not change the force.","hints":["Use Archimedes'' principle.","Check whether displaced volume or liquid density changes."],"target_seconds":60,"skill":"Concept application","difficulty":"Foundational","version":1,"source":"Original AI-authored practice · not official or calibrated MCAT material","passage":null}'::jsonb),
('expansion-01-04-01', '{"id":"expansion-01-04-01","topic":"Amino acids & proteins","section":"B/B","prompt":"At pH 7.4, which amino acid side chain is most likely to carry a negative charge?","options":["Lysine","Leucine","Aspartate","Serine"],"answer":2,"explanation":"Aspartate''s side-chain carboxyl group has a pKa well below 7.4 and is predominantly deprotonated. Lysine is typically positive; leucine and serine side chains are neutral.","hints":["Look for an acidic side-chain functional group.","A carboxyl group loses its proton when pH is well above its pKa."],"target_seconds":60,"skill":"Concept application","difficulty":"Foundational","version":1,"source":"Original AI-authored practice · not official or calibrated MCAT material","passage":null}'::jsonb),
('expansion-01-04-02', '{"id":"expansion-01-04-02","topic":"Amino acids & proteins","section":"B/B","prompt":"A protein is placed in a buffer whose pH is below its isoelectric point. What is its approximate net charge?","options":["Positive","Negative","Exactly zero at every pH","Determined only by its mass"],"answer":0,"explanation":"Below its isoelectric point, a protein is more protonated and generally has a net positive charge. At the isoelectric point its average net charge is zero.","hints":["Lower pH favors protonation.","Compare the buffer pH with the pH where the protein''s net charge is zero."],"target_seconds":60,"skill":"Concept application","difficulty":"Foundational","version":1,"source":"Original AI-authored practice · not official or calibrated MCAT material","passage":null}'::jsonb),
('expansion-01-04-03', '{"id":"expansion-01-04-03","topic":"Amino acids & proteins","section":"B/B","prompt":"Which interaction most directly stabilizes an alpha helix''s repeating secondary structure?","options":["Disulfide bonds between every adjacent residue","Peptide bonds between side chains","Hydrogen bonds exclusively between side chains","Hydrogen bonds between backbone carbonyl and amide groups"],"answer":3,"explanation":"An alpha helix is stabilized by hydrogen bonds between backbone C=O and N–H groups, commonly residues i and i+4. Side chains influence helix propensity but do not form the defining repeating hydrogen bonds.","hints":["Focus on the repeating polypeptide backbone.","Identify hydrogen-bond donors and acceptors in peptide groups."],"target_seconds":60,"skill":"Concept application","difficulty":"Foundational","version":1,"source":"Original AI-authored practice · not official or calibrated MCAT material","passage":null}'::jsonb),
('expansion-01-04-04', '{"id":"expansion-01-04-04","topic":"Amino acids & proteins","section":"B/B","prompt":"A reducing reagent breaks disulfide bonds in a protein. Which residues formed those bonds?","options":["Two methionines","Two cysteines","A lysine and an aspartate","Two glycines"],"answer":1,"explanation":"Oxidation of two cysteine thiol groups creates a disulfide bond. Reduction restores the thiols. Methionine contains sulfur but lacks a thiol group.","hints":["Which side chain contains a thiol?","A disulfide links two sulfur atoms formerly present as –SH groups."],"target_seconds":45,"skill":"Concept application","difficulty":"Foundational","version":1,"source":"Original AI-authored practice · not official or calibrated MCAT material","passage":null}'::jsonb),
('expansion-01-04-05', '{"id":"expansion-01-04-05","topic":"Amino acids & proteins","section":"B/B","prompt":"Which substitution is most likely to disrupt the hydrophobic core of a soluble globular protein?","options":["Leucine to aspartate","Leucine to isoleucine","Valine to leucine","Isoleucine to valine"],"answer":0,"explanation":"Replacing a nonpolar leucine with typically charged aspartate introduces an unfavorable polar group into a hydrophobic core. The other substitutions retain nonpolar side chains, although exact structural effects depend on context.","hints":["Compare side-chain polarity and charge.","A charged side chain is usually poorly accommodated in a nonpolar interior."],"target_seconds":60,"skill":"Concept application","difficulty":"Foundational","version":1,"source":"Original AI-authored practice · not official or calibrated MCAT material","passage":null}'::jsonb),
('expansion-01-04-06', '{"id":"expansion-01-04-06","topic":"Amino acids & proteins","section":"B/B","prompt":"Under reducing SDS-PAGE conditions, migration of most denatured proteins primarily distinguishes which property?","options":["Native enzymatic activity","Original net charge at neutral pH","Polypeptide molecular mass","Native number of bound ligands"],"answer":2,"explanation":"SDS unfolds proteins and imparts a roughly uniform negative charge-to-mass ratio; reduction separates disulfide-linked chains. The gel therefore primarily separates polypeptides by mass, with smaller chains migrating farther.","hints":["Consider what SDS and the reducing reagent do.","Native shape and charge differences are largely removed before gel separation."],"target_seconds":75,"skill":"Experimental reasoning","difficulty":"Foundational","version":1,"source":"Original AI-authored practice · not official or calibrated MCAT material","passage":null}'::jsonb),
('expansion-01-05-01', '{"id":"expansion-01-05-01","topic":"Genetics & gene expression","section":"B/B","prompt":"Two heterozygous carriers of a fully penetrant autosomal recessive condition have a child. What is the probability that the child is affected?","options":["0","1/2","3/4","1/4"],"answer":3,"explanation":"An Aa × Aa cross gives AA, Aa, Aa, and aa with equal probabilities. Only aa is affected, giving probability 1/4 for each child.","hints":["Draw an Aa × Aa Punnett square.","The affected genotype requires a recessive allele from each parent."],"target_seconds":60,"skill":"Quantitative reasoning","difficulty":"Foundational","version":1,"source":"Original AI-authored practice · not official or calibrated MCAT material","passage":null}'::jsonb),
('expansion-01-05-02', '{"id":"expansion-01-05-02","topic":"Genetics & gene expression","section":"B/B","prompt":"A DNA template segment is 3′-TAC GGA-5′. Which RNA sequence is synthesized from it?","options":["3′-AUG CCU-5′","5′-AUG CCU-3′","5′-TAC GGA-3′","5′-UAC GGA-3′"],"answer":1,"explanation":"RNA synthesis proceeds 5′ to 3′, complementary and antiparallel to the template. T pairs with A, A with U, C with G, and G with C, giving 5′-AUG CCU-3′.","hints":["RNA is complementary and antiparallel to its template.","Use uracil in RNA and write the product 5′ to 3′."],"target_seconds":75,"skill":"Concept application","difficulty":"Foundational","version":1,"source":"Original AI-authored practice · not official or calibrated MCAT material","passage":null}'::jsonb),
('expansion-01-05-03', '{"id":"expansion-01-05-03","topic":"Genetics & gene expression","section":"B/B","prompt":"A single nucleotide is inserted near the start of a protein-coding sequence, within an exon and outside a splice site. What is the most likely immediate coding consequence?","options":["A downstream reading-frame shift","No change because codons have one base","Deletion of the entire chromosome","Only the previous amino acid changes"],"answer":0,"explanation":"Insertion of one nucleotide changes how downstream bases are grouped into triplet codons. This frameshift can alter many amino acids and create a premature stop; its precise extent depends on sequence.","hints":["Codons are read in groups of three.","An insertion not divisible by three changes the downstream grouping."],"target_seconds":60,"skill":"Concept application","difficulty":"Foundational","version":1,"source":"Original AI-authored practice · not official or calibrated MCAT material","passage":null}'::jsonb),
('expansion-01-05-04', '{"id":"expansion-01-05-04","topic":"Genetics & gene expression","section":"B/B","prompt":"A heterozygote displays a phenotype intermediate between the two homozygotes. Which inheritance pattern best describes this observation?","options":["Complete dominance","Sex linkage","Incomplete dominance","Independent assortment"],"answer":2,"explanation":"Incomplete dominance produces an intermediate heterozygote phenotype. Codominance instead involves distinguishable expression of both allelic phenotypes, rather than an intermediate phenotype.","hints":["Compare the heterozygote with both homozygotes.","The dominant phenotype is not fully expressed in the heterozygote."],"target_seconds":45,"skill":"Concept application","difficulty":"Foundational","version":1,"source":"Original AI-authored practice · not official or calibrated MCAT material","passage":null}'::jsonb),
('expansion-01-05-05', '{"id":"expansion-01-05-05","topic":"Genetics & gene expression","section":"B/B","prompt":"Which PCR component most directly determines the boundaries of the DNA segment amplified?","options":["Free nucleotides","Magnesium ions","The reaction tube","The pair of primers"],"answer":3,"explanation":"Primers anneal to sequences flanking the target on opposite strands and supply 3′ ends for extension. Their binding sites determine the amplified region.","hints":["DNA polymerase must start from a preexisting 3′ end.","The two short complementary oligonucleotides flank the target."],"target_seconds":60,"skill":"Experimental reasoning","difficulty":"Foundational","version":1,"source":"Original AI-authored practice · not official or calibrated MCAT material","passage":null}'::jsonb),
('expansion-01-05-06', '{"id":"expansion-01-05-06","topic":"Genetics & gene expression","section":"B/B","prompt":"A eukaryotic pre-mRNA produces two mature mRNAs that retain different combinations of exons. What process explains this?","options":["DNA replication","Alternative splicing","Chromosome nondisjunction","Reverse transcription"],"answer":1,"explanation":"Alternative splicing joins different exon combinations from the same pre-mRNA. It can generate distinct protein isoforms without changing the underlying DNA sequence.","hints":["The difference arises during RNA processing.","Consider how intron removal and exon joining can vary."],"target_seconds":45,"skill":"Concept application","difficulty":"Foundational","version":1,"source":"Original AI-authored practice · not official or calibrated MCAT material","passage":null}'::jsonb),
('expansion-01-06-01', '{"id":"expansion-01-06-01","topic":"Cellular metabolism","section":"B/B","prompt":"What is the net ATP yield from glycolysis of one free glucose molecule to two pyruvate molecules?","options":["2 ATP","4 ATP","6 ATP","32 ATP"],"answer":0,"explanation":"Glycolysis consumes two ATP and produces four by substrate-level phosphorylation, for a net gain of two. It also produces two NADH; oxidative phosphorylation is not part of this ATP count.","hints":["Distinguish gross production from net gain.","Subtract the ATP investment from the four ATP produced."],"target_seconds":60,"skill":"Quantitative reasoning","difficulty":"Foundational","version":1,"source":"Original AI-authored practice · not official or calibrated MCAT material","passage":null}'::jsonb),
('expansion-01-06-02', '{"id":"expansion-01-06-02","topic":"Cellular metabolism","section":"B/B","prompt":"In human cells performing lactate fermentation, reducing pyruvate to lactate primarily allows glycolysis to continue by:","options":["Producing oxygen","Generating a proton gradient","Regenerating NAD+","Directly producing four additional ATP"],"answer":2,"explanation":"Lactate dehydrogenase oxidizes NADH to NAD+ as it reduces pyruvate. NAD+ is required by glyceraldehyde-3-phosphate dehydrogenase in glycolysis. The lactate reaction itself does not generate ATP.","hints":["Track the electron carrier, not just the carbon product.","Glycolysis needs an oxidized electron acceptor at the glyceraldehyde-3-phosphate step."],"target_seconds":60,"skill":"Concept application","difficulty":"Foundational","version":1,"source":"Original AI-authored practice · not official or calibrated MCAT material","passage":null}'::jsonb),
('expansion-01-06-03', '{"id":"expansion-01-06-03","topic":"Cellular metabolism","section":"B/B","prompt":"Where does the citric acid cycle occur in a typical human cell?","options":["Cytosol","Nucleus","Lysosomal lumen","Mitochondrial matrix"],"answer":3,"explanation":"The cycle occurs primarily in the mitochondrial matrix. Succinate dehydrogenase is associated with the inner mitochondrial membrane, but the cycle is conventionally localized to the matrix.","hints":["Distinguish glycolysis from mitochondrial oxidation.","Consider the compartment containing most citric acid cycle enzymes."],"target_seconds":45,"skill":"Concept application","difficulty":"Foundational","version":1,"source":"Original AI-authored practice · not official or calibrated MCAT material","passage":null}'::jsonb),
('expansion-01-06-04', '{"id":"expansion-01-06-04","topic":"Cellular metabolism","section":"B/B","prompt":"An uncoupler increases proton permeability of the inner mitochondrial membrane. With adequate fuel and oxygen, which immediate pattern is expected?","options":["ATP synthesis increases while oxygen use stops","ATP synthesis falls while electron transport can continue","The proton gradient becomes larger","NADH can no longer donate electrons solely because the membrane leaks"],"answer":1,"explanation":"Proton leakage dissipates the gradient used by ATP synthase. Electron transport can continue, often with increased oxygen consumption, while ATP production becomes less efficient and more energy is released as heat.","hints":["Separate electron flow from use of the proton gradient.","Protons can return without driving ATP synthase."],"target_seconds":75,"skill":"Experimental reasoning","difficulty":"Foundational","version":1,"source":"Original AI-authored practice · not official or calibrated MCAT material","passage":null}'::jsonb),
('expansion-01-06-05', '{"id":"expansion-01-06-05","topic":"Cellular metabolism","section":"B/B","prompt":"During the electron transport chain, oxygen serves primarily as:","options":["The terminal electron acceptor","The carbon source for glucose","A direct substrate of ATP synthase","The electron donor to complex I"],"answer":0,"explanation":"Oxygen accepts electrons at complex IV and is reduced to water. NADH donates electrons to complex I; ATP synthase uses the proton gradient rather than oxygen directly.","hints":["Trace electrons to the end of the chain.","The final acceptor combines with electrons and protons to form water."],"target_seconds":60,"skill":"Concept application","difficulty":"Foundational","version":1,"source":"Original AI-authored practice · not official or calibrated MCAT material","passage":null}'::jsonb),
('expansion-01-06-06', '{"id":"expansion-01-06-06","topic":"Cellular metabolism","section":"B/B","prompt":"One round of beta oxidation of a saturated fatty acyl-CoA longer than four carbons shortens the chain by how many carbon atoms?","options":["One","Three","Two","Four"],"answer":2,"explanation":"Each standard round releases a two-carbon acetyl-CoA and leaves a fatty acyl-CoA two carbons shorter. The final cleavage of a four-carbon chain yields two acetyl-CoA molecules.","hints":["Identify the carbon-containing product released each round.","An acetyl group contains two carbon atoms."],"target_seconds":60,"skill":"Concept application","difficulty":"Foundational","version":1,"source":"Original AI-authored practice · not official or calibrated MCAT material","passage":null}'::jsonb),
('expansion-01-07-01', '{"id":"expansion-01-07-01","topic":"Social psychology","section":"P/S","prompt":"A student attributes a classmate''s lateness to laziness without considering a transit delay. Which bias is best illustrated?","options":["Self-serving bias","Fundamental attribution error","Hindsight bias","Availability heuristic"],"answer":1,"explanation":"Fundamental attribution error overemphasizes dispositional explanations for another person''s behavior while underweighting situational causes. The vignette contrasts a trait judgment with a plausible external constraint.","hints":["Whose behavior is being explained, and how?","Compare a personality explanation with a situational explanation."],"target_seconds":60,"skill":"Concept application","difficulty":"Foundational","version":1,"source":"Original AI-authored practice · not official or calibrated MCAT material","passage":null}'::jsonb),
('expansion-01-07-02', '{"id":"expansion-01-07-02","topic":"Social psychology","section":"P/S","prompt":"A person publicly agrees with a group''s clearly wrong answer to avoid rejection, despite privately knowing the correct answer. What best explains this?","options":["Informational social influence","Classical conditioning","Social loafing","Normative social influence"],"answer":3,"explanation":"Normative influence reflects a desire for acceptance or avoidance of rejection. Informational influence would involve treating others'' judgments as evidence about what is correct.","hints":["The person is seeking acceptance rather than information.","Notice that private belief remains unchanged."],"target_seconds":60,"skill":"Concept application","difficulty":"Foundational","version":1,"source":"Original AI-authored practice · not official or calibrated MCAT material","passage":null}'::jsonb),
('expansion-01-07-03', '{"id":"expansion-01-07-03","topic":"Social psychology","section":"P/S","prompt":"A skilled pianist performs a well-practiced piece better in front of an audience than alone. Which concept best fits?","options":["Social facilitation","Group polarization","Deindividuation","Bystander effect"],"answer":0,"explanation":"Social facilitation describes improved performance on well-learned or simple tasks in the presence of others. An audience can impair performance on unfamiliar or difficult tasks instead.","hints":["The task is already well practiced.","Consider how an audience affects dominant, well-learned responses."],"target_seconds":60,"skill":"Concept application","difficulty":"Foundational","version":1,"source":"Original AI-authored practice · not official or calibrated MCAT material","passage":null}'::jsonb),
('expansion-01-07-04', '{"id":"expansion-01-07-04","topic":"Social psychology","section":"P/S","prompt":"Each person in a large crowd assumes someone else will call for help, reducing the likelihood that any one person acts. What mechanism is illustrated?","options":["Operant extinction","Cognitive dissonance","Diffusion of responsibility","Reciprocal determinism"],"answer":2,"explanation":"Diffusion of responsibility reduces an individual''s perceived obligation when others are present. It is one mechanism contributing to the bystander effect.","hints":["Responsibility is spread across multiple observers.","Each person expects another person to intervene."],"target_seconds":45,"skill":"Concept application","difficulty":"Foundational","version":1,"source":"Original AI-authored practice · not official or calibrated MCAT material","passage":null}'::jsonb),
('expansion-01-07-05', '{"id":"expansion-01-07-05","topic":"Social psychology","section":"P/S","prompt":"After joining a discussion, members of a mildly risk-seeking group endorse a more strongly risk-seeking position. This is an example of:","options":["Social loafing","Group polarization","Role strain","Stimulus discrimination"],"answer":1,"explanation":"Group polarization shifts a group''s average position toward a more extreme version of its initial tendency. It differs from groupthink, which emphasizes pressures suppressing critical evaluation.","hints":["Compare the direction of opinion before and after discussion.","The group moves farther in its preexisting direction."],"target_seconds":60,"skill":"Concept application","difficulty":"Foundational","version":1,"source":"Original AI-authored practice · not official or calibrated MCAT material","passage":null}'::jsonb),
('expansion-01-07-06', '{"id":"expansion-01-07-06","topic":"Social psychology","section":"P/S","prompt":"A person who values health but smokes minimizes evidence that smoking is harmful. Which concept best explains this rationalization?","options":["Sensory adaptation","Secure attachment","Observational learning","Cognitive dissonance reduction"],"answer":3,"explanation":"Conflict between a health-related belief and smoking behavior can create cognitive dissonance. Discounting evidence reduces the perceived inconsistency without changing the behavior.","hints":["Identify the conflict between belief and behavior.","Changing an interpretation can reduce discomfort from inconsistent cognitions."],"target_seconds":60,"skill":"Concept application","difficulty":"Foundational","version":1,"source":"Original AI-authored practice · not official or calibrated MCAT material","passage":null}'::jsonb),
('expansion-01-08-01', '{"id":"expansion-01-08-01","topic":"Research methods","section":"P/S","prompt":"Investigators randomly assign participants to an intervention or control group. What is the main purpose of random assignment?","options":["Guarantee a representative population sample","Ensure the hypothesis is correct","Reduce systematic baseline differences between groups","Eliminate every measurement error"],"answer":2,"explanation":"Random assignment balances measured and unmeasured confounders in expectation, improving causal inference. It does not guarantee perfect balance or population representativeness; random sampling addresses the latter.","hints":["Distinguish assignment to groups from selection into a sample.","Think about preexisting differences that could explain the outcome."],"target_seconds":75,"skill":"Experimental reasoning","difficulty":"Foundational","version":1,"source":"Original AI-authored practice · not official or calibrated MCAT material","passage":null}'::jsonb),
('expansion-01-08-02', '{"id":"expansion-01-08-02","topic":"Research methods","section":"P/S","prompt":"A study finds that coffee intake and stress scores are positively correlated. Which conclusion is justified by correlation alone?","options":["Higher coffee intake is associated with higher stress scores","Coffee necessarily causes stress","Stress cannot influence coffee intake","No third variable could explain the association"],"answer":0,"explanation":"A positive correlation establishes an association in the observed data. Direction of causation and confounding remain unresolved without additional design or evidence.","hints":["Separate an association from a causal explanation.","Reverse causation and common causes are still possible."],"target_seconds":60,"skill":"Experimental reasoning","difficulty":"Foundational","version":1,"source":"Original AI-authored practice · not official or calibrated MCAT material","passage":null}'::jsonb),
('expansion-01-08-03', '{"id":"expansion-01-08-03","topic":"Research methods","section":"P/S","prompt":"A depression questionnaire gives similar scores on repeated administrations when participants'' underlying states are stable. Which property is most directly demonstrated?","options":["External validity","Random assignment","Criterion validity","Test–retest reliability"],"answer":3,"explanation":"Test–retest reliability concerns measurement consistency over time when the construct is stable. Consistency alone does not establish that the instrument measures depression accurately.","hints":["The evidence concerns consistency across time.","Distinguish reliability from whether the intended construct is actually measured."],"target_seconds":60,"skill":"Experimental reasoning","difficulty":"Foundational","version":1,"source":"Original AI-authored practice · not official or calibrated MCAT material","passage":null}'::jsonb),
('expansion-01-08-04', '{"id":"expansion-01-08-04","topic":"Research methods","section":"P/S","prompt":"A researcher rejects a null hypothesis that is actually true. What has occurred?","options":["A type II error","A type I error","Perfect statistical power","A true negative"],"answer":1,"explanation":"A type I error is a false positive: rejecting a true null hypothesis. A type II error is failing to reject a false null hypothesis.","hints":["The claimed effect is a false positive.","Map false positive to type I and false negative to type II."],"target_seconds":45,"skill":"Concept application","difficulty":"Foundational","version":1,"source":"Original AI-authored practice · not official or calibrated MCAT material","passage":null}'::jsonb),
('expansion-01-08-05', '{"id":"expansion-01-08-05","topic":"Research methods","section":"P/S","prompt":"In a screening study, 80 of 100 people who truly have a condition test positive. What is the test''s sensitivity?","options":["80%","20%","Cannot be found without the false-positive count","125%"],"answer":0,"explanation":"Sensitivity is true positives divided by all people with the condition: 80/100 = 80%. False positives are needed for other measures, such as positive predictive value, but not for this calculation.","hints":["Condition on having the condition.","Divide true positives by true positives plus false negatives."],"target_seconds":75,"skill":"Quantitative reasoning","difficulty":"Foundational","version":1,"source":"Original AI-authored practice · not official or calibrated MCAT material","passage":null}'::jsonb),
('expansion-01-08-06', '{"id":"expansion-01-08-06","topic":"Research methods","section":"P/S","prompt":"A study operationalizes stress as a participant''s score on a specified questionnaire. What does this operational definition accomplish?","options":["Proves that stress has only one cause","Guarantees a causal conclusion","Specifies how an abstract construct is measured","Ensures that all participants have identical stress"],"answer":2,"explanation":"An operational definition translates a construct into a concrete measurement or procedure. It supports reproducibility but does not by itself establish validity, causality, or equal scores.","hints":["Ask how another researcher would reproduce the measurement.","The definition connects an abstract idea to an observable procedure."],"target_seconds":60,"skill":"Experimental reasoning","difficulty":"Foundational","version":1,"source":"Original AI-authored practice · not official or calibrated MCAT material","passage":null}'::jsonb)
